CREATE TABLE metric_snapshots(id UUID PRIMARY KEY,device_id UUID NOT NULL REFERENCES devices(id) ON DELETE CASCADE,recorded_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,latency_ms DOUBLE PRECISION,packet_loss_percent DOUBLE PRECISION,cpu_percent DOUBLE PRECISION,memory_percent DOUBLE PRECISION,bandwidth_mbps DOUBLE PRECISION,status VARCHAR(30));CREATE INDEX idx_metric_device_time ON metric_snapshots(device_id,recorded_at DESC);